    INSERT INTO "Question" ("id", "assessmentId", "textEn", "textFr", "order", "points", "setNumber") VALUES
      ('0adbe3a9-703a-401a-8411-8e66742499e1', a_id, $bp$What question does the Series Foreword say every serious Kingdom citizen eventually asks?$bp$, $bp$Quelle question l'Avant-propos de la série dit-il que tout citoyen sérieux du Royaume finit par poser ?$bp$, 0, 1, 2),
      ('80a26e18-e74e-42aa-814c-99c217b10c0a', a_id, $bp$How does the Introduction use the Apostle Paul's life?$bp$, $bp$Comment l'Introduction utilise-t-elle la vie de l'apôtre Paul ?$bp$, 1, 1, 2),
      ('9178f666-8095-4b13-9b8e-21f982198147', a_id, $bp$Which gap does Chapter One call the first and most fundamental?$bp$, $bp$Quel écart le chapitre un appelle-t-il le premier et le plus fondamental ?$bp$, 2, 1, 2),
      ('52363305-eaf1-4334-ab01-faa5b0b94208', a_id, $bp$What does the Greek word musterion, mystery, mean in Matthew 13:11, according to the book?$bp$, $bp$Que signifie le mot grec musterion, mystère, en Matthieu 13.11, selon le livre ?$bp$, 3, 1, 2),
      ('09cc99ca-d87a-4fc9-9589-3fb9f01aac73', a_id, $bp$What did Abraham's life show about closing the gap, according to Chapter One?$bp$, $bp$Qu'est-ce que la vie d'Abraham a montré sur la façon de combler l'écart, selon le chapitre un ?$bp$, 4, 1, 2),
      ('70f2e42e-4310-414a-8e73-d1ba0b4a0d7d', a_id, $bp$In the Passover illustration, why could a household still face judgment?$bp$, $bp$Dans l'illustration de la Pâque, pourquoi une famille pouvait-elle encore subir le jugement ?$bp$, 5, 1, 2),
      ('83de92b7-efcd-41d5-a2e3-d8f0ce76d04b', a_id, $bp$What was Naaman's problem when told to wash in the Jordan seven times?$bp$, $bp$Quel était le problème de Naaman quand on lui a dit de se laver sept fois dans le Jourdain ?$bp$, 6, 1, 2),
      ('403b2480-6ba2-4edf-9fca-e0cc43e79d91', a_id, $bp$According to Chapter Two, what are Kingdom systems such as faith and prayer?$bp$, $bp$Selon le chapitre deux, que sont les systèmes du Royaume comme la foi et la prière ?$bp$, 7, 1, 2),
      ('1cd39a1d-92e2-4ff1-ae9b-ae73fa166453', a_id, $bp$What does the phrase "when he came to himself" in the prodigal son's story show?$bp$, $bp$Que montre l'expression « étant rentré en lui-même » dans l'histoire du fils prodigue ?$bp$, 8, 1, 2),
      ('3c6dadfb-0909-472d-811e-3208d5a1a6bf', a_id, $bp$What does the Hebrew word damah, translated destroyed in Hosea 4:6, mean?$bp$, $bp$Que signifie le mot hébreu damah, traduit par détruit en Osée 4.6 ?$bp$, 9, 1, 2),
      ('14933653-e635-467a-87df-310ac470c2d7', a_id, $bp$What does the book say are the primary targets in 2 Corinthians 10:4-5?$bp$, $bp$Selon le livre, quelles sont les cibles principales en 2 Corinthiens 10.4-5 ?$bp$, 10, 1, 2),
      ('1f8e46e1-1cf6-424a-814e-e17350ce87d2', a_id, $bp$What does the book say Kingdom protocols are?$bp$, $bp$Selon le livre, que sont les protocoles du Royaume ?$bp$, 11, 1, 2),
      ('8b0eb1e1-ab6e-4439-a26b-a39efa935079', a_id, $bp$How did Joseph's life show Kingdom systems at work?$bp$, $bp$Comment la vie de Joseph a-t-elle montré les systèmes du Royaume à l'œuvre ?$bp$, 12, 1, 2),
      ('c59320f3-7b82-4fb0-bf32-1f3ae374a3a1', a_id, $bp$What are the three components of the sowing and reaping system?$bp$, $bp$Quels sont les trois éléments du système du semer et du récolter ?$bp$, 13, 1, 2),
      ('cbc5e8d2-3547-4283-8fb1-2efd2b0ea0ca', a_id, $bp$What are the four components of key alignment in Chapter Five?$bp$, $bp$Quels sont les quatre éléments de l'alignement d'une clé au chapitre cinq ?$bp$, 14, 1, 2),
      ('2a0c16ab-0e7e-4be8-a849-077bd09445fd', a_id, $bp$How does the book describe wisdom in its list of biblical terms for the keys?$bp$, $bp$Comment le livre décrit-il la sagesse dans sa liste de termes bibliques pour les clés ?$bp$, 15, 1, 2),
      ('77ed36cf-f40a-4407-bfdb-0fabd13901b0', a_id, $bp$In Tier One of the seven tiers, which question do the keys answer?$bp$, $bp$Au niveau Un des sept niveaux, à quelle question les clés répondent-elles ?$bp$, 16, 1, 2),
      ('4a1b35ec-bbab-404b-b2e5-98b3ca63cb0b', a_id, $bp$What does the Greek word methistemi, in Colossians 1:13, show about the new birth?$bp$, $bp$Que montre le mot grec methistemi, en Colossiens 1.13, au sujet de la nouvelle naissance ?$bp$, 17, 1, 2),
      ('95e645a6-e7dc-4336-a79e-b0411ee5852f', a_id, $bp$What did Nicodemus do later, according to John 19:39 in the book?$bp$, $bp$Selon le livre, que fit Nicodème plus tard, d'après Jean 19.39 ?$bp$, 18, 1, 2),
      ('5b5031e6-c64b-4959-82be-43aef117750b', a_id, $bp$Why does the book compare the unsaved person to a radio receiver?$bp$, $bp$Pourquoi le livre compare-t-il la personne non sauvée à un récepteur radio ?$bp$, 19, 1, 2),
      ('f2279c5e-0eb6-4364-9090-5af327faf161', a_id, $bp$The book says this series is the practical companion to the Rights of Kingdom Citizens series.$bp$, $bp$Le livre dit que cette série est le complément pratique de la série Les Droits des citoyens du Royaume.$bp$, 20, 1, 2),
      ('9d9e5bc6-698c-410a-bfba-6b12c85027ad', a_id, $bp$The book teaches that a believer's position in Christ grows stronger as he works harder.$bp$, $bp$Le livre enseigne que la position d'un croyant en Christ se renforce à mesure qu'il travaille davantage.$bp$, 21, 1, 2),
      ('d0d2a45e-c03e-42aa-ad8f-35182cc57c80', a_id, $bp$The book teaches that Kingdom laws work for whoever works them, whatever their background.$bp$, $bp$Le livre enseigne que les lois du Royaume fonctionnent pour quiconque les met en œuvre, quel que soit son passé.$bp$, 22, 1, 2),
      ('dfcc389b-88a1-4d1e-98da-513c18efed6f', a_id, $bp$The book teaches that a believer needs all fifty-three keys before he can begin to walk in dominion.$bp$, $bp$Le livre enseigne qu'un croyant a besoin des cinquante-trois clés avant de pouvoir commencer à marcher dans la domination.$bp$, 23, 1, 2),
      ('cd405f81-8412-4d33-920e-d7f56265f08a', a_id, $bp$The book teaches that Zacchaeus made his promises as conditions he had to meet in order to be saved.$bp$, $bp$Le livre enseigne que Zachée a fait ses promesses comme des conditions à remplir pour être sauvé.$bp$, 24, 1, 2);
    INSERT INTO "Option" ("id", "questionId", "textEn", "textFr", "isCorrect", "order") VALUES
      ('41f01161-4dba-433a-ac3f-52d399d9f459', '0adbe3a9-703a-401a-8411-8e66742499e1', $bp$“I know what the enemy does, so how can I ever hope to stop him?”$bp$, $bp$« Je sais ce que fait l'ennemi, alors comment puis-je espérer l'arrêter ? »$bp$, FALSE, 0),
      ('41ef2a8b-3bd4-47d8-9ec8-03e9aada03ce', '0adbe3a9-703a-401a-8411-8e66742499e1', $bp$“I know what the Bible says, so why do I still feel so far from God?”$bp$, $bp$« Je sais ce que dit la Bible, alors pourquoi est-ce que je me sens encore si loin de Dieu ? »$bp$, FALSE, 1),
      ('d7ba8b04-da83-48a4-aac6-279adeebb6b0', '0adbe3a9-703a-401a-8411-8e66742499e1', $bp$“I know what my rights are, so how do I actually walk in them?”$bp$, $bp$« Je connais mes droits, alors comment y marcher réellement ? »$bp$, TRUE, 2),
      ('7791fcda-a15f-422f-97b6-2d5effb7c059', '0adbe3a9-703a-401a-8411-8e66742499e1', $bp$“I know what my calling is, so when will the door finally open for me?”$bp$, $bp$« Je connais mon appel, alors quand la porte s'ouvrira-t-elle enfin pour moi ? »$bp$, FALSE, 3),
      ('6a918d3d-e8b6-4ce0-91e9-5c6ae7e0bb4c', '80a26e18-e74e-42aa-814c-99c217b10c0a', $bp$He rested and did nothing after his conversion, showing that grace needs no human response$bp$, $bp$Il s'est reposé sans rien faire après sa conversion, montrant que la grâce n'exige aucune réponse de l'homme$bp$, FALSE, 0),
      ('6f3c7033-7b61-4fed-98d4-5515ca038ccc', '80a26e18-e74e-42aa-814c-99c217b10c0a', $bp$He dropped every Kingdom discipline after Damascus, showing that rights work on their own$bp$, $bp$Il a abandonné toute discipline du Royaume après Damas, montrant que les droits fonctionnent d'eux-mêmes$bp$, FALSE, 1),
      ('64198596-c20f-4fc7-8b0c-bb859745b1a7', '80a26e18-e74e-42aa-814c-99c217b10c0a', $bp$He prayed, fasted, and gave, as one who honoured the finished work and did not doubt it$bp$, $bp$Il a prié, jeûné et donné, comme quelqu'un qui honorait l'œuvre achevée et n'en doutait pas$bp$, TRUE, 2),
      ('b942f4a1-3842-4852-bbf4-fd45fa04d06a', '80a26e18-e74e-42aa-814c-99c217b10c0a', $bp$He worked hard to earn his place in Christ, showing that grace must be added to by effort$bp$, $bp$Il a travaillé dur pour gagner sa place en Christ, montrant que la grâce doit être complétée par l'effort$bp$, FALSE, 3),
      ('7e13efe8-4d91-40e0-a2af-220c4b80f81f', '9178f666-8095-4b13-9b8e-21f982198147', $bp$The gap of timing: not knowing when God will answer your request$bp$, $bp$L'écart du temps : ne pas savoir quand Dieu répondra à votre demande$bp$, FALSE, 0),
      ('3c27aa60-090f-4a20-aa6c-16a99961350d', '9178f666-8095-4b13-9b8e-21f982198147', $bp$The gap of prayer: not knowing the right words to use before God$bp$, $bp$L'écart de la prière : ne pas connaître les bons mots à employer devant Dieu$bp$, FALSE, 1),
      ('dced029e-d48c-4271-9b01-911c7892e871', '9178f666-8095-4b13-9b8e-21f982198147', $bp$The gap of money: not having enough resources to fund the Kingdom$bp$, $bp$L'écart de l'argent : ne pas avoir assez de ressources pour financer le Royaume$bp$, FALSE, 2),
      ('385f2313-2b66-495d-958e-f6ac64ed2b84', '9178f666-8095-4b13-9b8e-21f982198147', $bp$The gap of identity: not knowing who you are as a Kingdom citizen$bp$, $bp$L'écart de l'identité : ne pas savoir qui vous êtes en tant que citoyen du Royaume$bp$, TRUE, 3),
      ('a2bf54b1-d2ba-4271-a7bd-f1ee970b459f', '52363305-eaf1-4334-ab01-faa5b0b94208', $bp$Something hidden from those outside but revealed to those inside who seek it$bp$, $bp$Quelque chose de caché à ceux du dehors, mais révélé à ceux du dedans qui le cherchent$bp$, TRUE, 0),
      ('a7eae167-fe9d-4212-a388-6124915f736f', '52363305-eaf1-4334-ab01-faa5b0b94208', $bp$Something secret that is shared only after years in a church's inner circle$bp$, $bp$Quelque chose de secret qui n'est partagé qu'après des années dans le cercle intime d'une église$bp$, FALSE, 1),
      ('553b790c-d990-4dcf-81d0-487c2e2fd07a', '52363305-eaf1-4334-ab01-faa5b0b94208', $bp$Something reserved for prophets and apostles and kept from ordinary believers$bp$, $bp$Quelque chose de réservé aux prophètes et aux apôtres et gardé loin des croyants ordinaires$bp$, FALSE, 2),
      ('c270083c-e896-4a71-af6a-a82b38d05a9a', '52363305-eaf1-4334-ab01-faa5b0b94208', $bp$Something permanently unknowable that no believer can fully understand on earth$bp$, $bp$Quelque chose de définitivement inconnaissable qu'aucun croyant ne peut pleinement comprendre sur la terre$bp$, FALSE, 3),
      ('e73cb057-e72e-4b24-a023-503da2e0e771', '09cc99ca-d87a-4fc9-9589-3fb9f01aac73', $bp$The gap closed the moment God spoke, so he did nothing more except wait for it to happen$bp$, $bp$L'écart s'est comblé au moment où Dieu a parlé, et il n'a plus rien fait d'autre qu'attendre que cela arrive$bp$, FALSE, 0),
      ('0f1ab6d8-d09d-4425-8728-97878476cb0d', '09cc99ca-d87a-4fc9-9589-3fb9f01aac73', $bp$The gap closed only after he left his family, and he never needed a covenant with God$bp$, $bp$L'écart ne s'est comblé qu'après qu'il eut quitté sa famille, et il n'a jamais eu besoin d'une alliance avec Dieu$bp$, FALSE, 1),
      ('a69eb928-5f64-4a98-aa61-e5c0024d87c0', '09cc99ca-d87a-4fc9-9589-3fb9f01aac73', $bp$The gap closed through faith, covenant, obedience, and worship, though he was not perfect$bp$, $bp$L'écart s'est comblé par la foi, l'alliance, l'obéissance et l'adoration, bien qu'il n'ait pas été parfait$bp$, TRUE, 2),
      ('28355f9d-6f0f-44b8-880d-ab217deb0450', '09cc99ca-d87a-4fc9-9589-3fb9f01aac73', $bp$The gap closed because he was sinless and had no struggles or doubts at all in his life$bp$, $bp$L'écart s'est comblé parce qu'il était sans péché et n'avait aucune lutte ni aucun doute dans sa vie$bp$, FALSE, 3),
      ('9a8683a5-aabe-4972-9ca0-963dd5105e04', '70f2e42e-4310-414a-8e73-d1ba0b4a0d7d', $bp$The blood was weak, so the household needed to add its own offering as well$bp$, $bp$Le sang était faible, et la famille devait ajouter sa propre offrande$bp$, FALSE, 0),
      ('590d27c7-8339-4f6b-9c41-c2a834462902', '70f2e42e-4310-414a-8e73-d1ba0b4a0d7d', $bp$The blood was available, but the lamb had not been chosen by the priests$bp$, $bp$Le sang était disponible, mais l'agneau n'avait pas été choisi par les prêtres$bp$, FALSE, 1),
      ('810864ee-60f1-4dd7-bba3-11ed2c1af918', '70f2e42e-4310-414a-8e73-d1ba0b4a0d7d', $bp$The blood was sufficient, but the household did not apply it to its doorposts$bp$, $bp$Le sang était suffisant, mais la famille ne l'avait pas appliqué sur ses poteaux de porte$bp$, TRUE, 2),
      ('2f6edb0b-76c1-4cf7-bff5-d5d250cdb328', '70f2e42e-4310-414a-8e73-d1ba0b4a0d7d', $bp$The blood was applied, but the household did not know the right prayer to say$bp$, $bp$Le sang était appliqué, mais la famille ne connaissait pas la bonne prière à dire$bp$, FALSE, 3),
      ('dd7f9ea2-6045-44e7-9060-87680e7ae82d', '83de92b7-efcd-41d5-a2e3-d8f0ce76d04b', $bp$His pride and expectations made him furious, and he nearly refused the Kingdom protocol$bp$, $bp$Son orgueil et ses attentes l'ont rendu furieux, et il a presque refusé le protocole du Royaume$bp$, TRUE, 0),
      ('df8e9174-a93a-49aa-b239-d662103ecee1', '83de92b7-efcd-41d5-a2e3-d8f0ce76d04b', $bp$His fear of the river made him refuse, and his servants took his place in the water$bp$, $bp$Sa peur du fleuve l'a fait refuser, et ses serviteurs ont pris sa place dans l'eau$bp$, FALSE, 1),
      ('ccf73348-4a19-4f0f-b598-c9ef4d2a3135', '83de92b7-efcd-41d5-a2e3-d8f0ce76d04b', $bp$His doubt about Elisha's power made him leave, and he never returned to be healed$bp$, $bp$Son doute sur la puissance d'Élisée l'a fait partir, et il n'est jamais revenu pour être guéri$bp$, FALSE, 2),
      ('c8a93150-1e37-496f-b50e-e0a3e0355fac', '83de92b7-efcd-41d5-a2e3-d8f0ce76d04b', $bp$His anger at the king made him delay, and he washed once and then went home angry$bp$, $bp$Sa colère contre le roi l'a fait tarder, et il s'est lavé une fois puis est rentré chez lui en colère$bp$, FALSE, 3),
      ('ca60ecfe-2ae4-4e93-8d3f-a74055c86dd9', '403b2480-6ba2-4edf-9fca-e0cc43e79d91', $bp$Instruments of earning and proving, not instruments of receiving$bp$, $bp$Des instruments pour gagner et prouver, et non des instruments pour recevoir$bp$, FALSE, 0),
      ('b8862c09-3aa4-43ac-9c65-612df3171418', '403b2480-6ba2-4edf-9fca-e0cc43e79d91', $bp$Instruments of receiving and releasing, not instruments of earning$bp$, $bp$Des instruments pour recevoir et libérer, et non des instruments pour gagner$bp$, TRUE, 1),
      ('674871d0-008e-4187-bff0-8b928bc348c3', '403b2480-6ba2-4edf-9fca-e0cc43e79d91', $bp$Instruments of ritual and tradition, not instruments of real power$bp$, $bp$Des instruments de rituel et de tradition, et non des instruments de réelle puissance$bp$, FALSE, 2),
      ('8d659023-d923-48aa-bc66-b8570cd6dce4', '403b2480-6ba2-4edf-9fca-e0cc43e79d91', $bp$Instruments of judgment and testing, not instruments of releasing$bp$, $bp$Des instruments de jugement et d'épreuve, et non des instruments pour libérer$bp$, FALSE, 3),
      ('1be8ba4a-1253-4a53-a083-c2ee6dc1c057', '1cd39a1d-92e2-4ff1-ae9b-ae73fa166453', $bp$Sudden hunger: he felt the pain in his stomach, and only the need for bread moved him$bp$, $bp$Une faim soudaine : il a senti la douleur dans son estomac, et seul le besoin de pain l'a ému$bp$, FALSE, 0),
      ('4eda3d86-4d3b-4c05-b9dc-49d856d2bf4f', '1cd39a1d-92e2-4ff1-ae9b-ae73fa166453', $bp$Pure regret: he felt sorry for his waste, and wished the money back in his hands$bp$, $bp$Un pur regret : il a eu du chagrin pour son gaspillage, et aurait voulu retrouver son argent$bp$, FALSE, 1),
      ('6c992b6f-341c-47b0-8ada-20af0316f176', '1cd39a1d-92e2-4ff1-ae9b-ae73fa166453', $bp$Mental illness: he lost his mind in the far country, and the father cured him at home$bp$, $bp$Une maladie mentale : il a perdu la raison dans le pays lointain, et le père l'a guéri à la maison$bp$, FALSE, 2),
      ('e30b6ebe-bfff-403d-99d9-019e0ca93941', '1cd39a1d-92e2-4ff1-ae9b-ae73fa166453', $bp$Identity recovery: he remembered whose son he was, and his circumstances began to change$bp$, $bp$Le retour de l'identité : il s'est souvenu de qui il était le fils, et ses circonstances ont commencé à changer$bp$, TRUE, 3),
      ('385a8c13-42b4-43ca-b2dc-8133e44d483f', '3c6dadfb-0909-472d-811e-3208d5a1a6bf', $bp$To be scattered, sent far away, and taken into exile: a long delay$bp$, $bp$Être dispersé, envoyé au loin et emmené en exil : un long retard$bp$, FALSE, 0),
      ('2a37851f-8e5a-4fc7-b289-deae4e0cfb81', '3c6dadfb-0909-472d-811e-3208d5a1a6bf', $bp$To be warned, corrected, and turned back: a gentle discipline from God$bp$, $bp$Être averti, corrigé et ramené : une douce discipline de Dieu$bp$, FALSE, 1),
      ('d7c1a559-185e-4dcf-a145-3c6e96e7e4e9', '3c6dadfb-0909-472d-811e-3208d5a1a6bf', $bp$To be tested, refined, and made pure: a necessary trial for growth$bp$, $bp$Être éprouvé, raffiné et rendu pur : une épreuve nécessaire pour grandir$bp$, FALSE, 2),
      ('b4120e0f-6beb-4908-8fec-19cc088bc299', '3c6dadfb-0909-472d-811e-3208d5a1a6bf', $bp$To be cut down, silenced, and brought to ruin: a catastrophic loss$bp$, $bp$Être abattu, réduit au silence et conduit à la ruine : une perte catastrophique$bp$, TRUE, 3),
      ('930637c7-ddae-4486-b5c3-ca0b390223fa', '14933653-e635-467a-87df-310ac470c2d7', $bp$Sinful people and false teachers: outside enemies that attack the church from every side$bp$, $bp$Les pécheurs et les faux docteurs : des ennemis extérieurs qui attaquent l'Église de toutes parts$bp$, FALSE, 0),
      ('114dc7cb-d3f5-4347-9a88-08cbe3b1e276', '14933653-e635-467a-87df-310ac470c2d7', $bp$Natural disasters and sickness: outside events that must be rebuked by faith in the Word$bp$, $bp$Les catastrophes naturelles et la maladie : des événements extérieurs qu'il faut réprimander par la foi en la Parole$bp$, FALSE, 1),
      ('530ad9c6-6196-4135-8a3d-6cec71f90d56', '14933653-e635-467a-87df-310ac470c2d7', $bp$Demons and evil spirits: outside powers that must be cast out of every city and home$bp$, $bp$Les démons et les esprits mauvais : des puissances extérieures qu'il faut chasser de chaque ville et de chaque maison$bp$, FALSE, 2),
      ('7b71602a-f785-4eba-8a6f-31175cf8d760', '14933653-e635-467a-87df-310ac470c2d7', $bp$Arguments and wrong thought systems: inner distortions of knowledge, not mainly demons$bp$, $bp$Les raisonnements et les systèmes de pensée erronés : des distorsions intérieures de la connaissance, pas principalement des démons$bp$, TRUE, 3),
      ('d9faf68c-1114-446a-a085-0e22297b7f5c', '1f8e46e1-1cf6-424a-814e-e17350ce87d2', $bp$Hidden secrets of the Kingdom, revealed only to mature leaders after long service$bp$, $bp$Des secrets cachés du Royaume, révélés seulement aux dirigeants mûrs après un long service$bp$, FALSE, 0),
      ('fbac4a64-4684-4c90-ba88-42ccb5c4fe46', '1f8e46e1-1cf6-424a-814e-e17350ce87d2', $bp$Prescribed sequences of action that engage Kingdom laws, such as prayer and fasting$bp$, $bp$Des séquences d'action prescrites qui engagent les lois du Royaume, comme la prière et le jeûne$bp$, TRUE, 1),
      ('102faa18-5a37-47cb-94ba-e02f94ee46eb', '1f8e46e1-1cf6-424a-814e-e17350ce87d2', $bp$Fixed principles that govern spiritual reality, as gravity governs the natural world$bp$, $bp$Des principes fixes qui gouvernent la réalité spirituelle, comme la gravité gouverne le monde naturel$bp$, FALSE, 2),
      ('4d736498-2008-419b-8023-e9c9be9c6161', '1f8e46e1-1cf6-424a-814e-e17350ce87d2', $bp$Divine structures and patterns within which Kingdom power is released in order$bp$, $bp$Des structures et des modèles divins à l'intérieur desquels la puissance du Royaume est libérée dans l'ordre$bp$, FALSE, 3),
      ('39169a76-6f9f-4950-b175-1719346dc2f0', '8b0eb1e1-ab6e-4439-a26b-a39efa935079', $bp$He waited quietly in prison for God to act, and was lifted out when the time came$bp$, $bp$Il a attendu en silence en prison que Dieu agisse, et il en a été sorti quand le moment est venu$bp$, FALSE, 0),
      ('702293aa-a94e-4d41-b472-acab0edfd9aa', '8b0eb1e1-ab6e-4439-a26b-a39efa935079', $bp$He used integrity and wisdom even in prison, and rose to second place under Pharaoh$bp$, $bp$Il a usé d'intégrité et de sagesse même en prison, et s'est élevé à la deuxième place après Pharaon$bp$, TRUE, 1),
      ('dbd0bd0d-f938-4b31-9af2-0bdc4e0fd288', '8b0eb1e1-ab6e-4439-a26b-a39efa935079', $bp$He used his own cleverness to win Pharaoh over, and the systems played no real part$bp$, $bp$Il a usé de sa propre habileté pour gagner Pharaon, et les systèmes n'ont joué aucun rôle réel$bp$, FALSE, 2),
      ('e798fc1a-e2d7-4206-abab-bc0a98c390f6', '8b0eb1e1-ab6e-4439-a26b-a39efa935079', $bp$He asked his brothers for help in Egypt, and they restored him to his father's house$bp$, $bp$Il a demandé de l'aide à ses frères en Égypte, et ils l'ont rétabli dans la maison de son père$bp$, FALSE, 3),
      ('8b1d0e87-e634-4a67-8fc3-69b66eb4f650', 'c59320f3-7b82-4fb0-bf32-1f3ae374a3a1', $bp$The seed you sow, the soil you sow in, and the season of reaping$bp$, $bp$La semence que vous semez, le sol dans lequel vous semez et la saison de la récolte$bp$, TRUE, 0),
      ('3ec9b03a-3b1f-4ce1-9b9c-273c8d1b0e52', 'c59320f3-7b82-4fb0-bf32-1f3ae374a3a1', $bp$The seed you keep, the barn you build, and the market you reach$bp$, $bp$La semence que vous gardez, la grange que vous bâtissez et le marché que vous atteignez$bp$, FALSE, 1),
      ('4451a092-abb7-4a07-9d58-47cc0220e664', 'c59320f3-7b82-4fb0-bf32-1f3ae374a3a1', $bp$The sower you trust, the field you own, and the size of the harvest$bp$, $bp$Le semeur en qui vous avez confiance, le champ que vous possédez et la taille de la récolte$bp$, FALSE, 2),
      ('ddddc978-1d1c-49cf-a97b-3bda224daafc', 'c59320f3-7b82-4fb0-bf32-1f3ae374a3a1', $bp$The tithe you give, the church you attend, and the year you start$bp$, $bp$La dîme que vous donnez, l'église que vous fréquentez et l'année où vous commencez$bp$, FALSE, 3),
      ('e8559b84-420d-4ab6-a2cc-995e229212d6', 'cbc5e8d2-3547-4283-8fb1-2efd2b0ea0ca', $bp$Revelation to know the key, faith to believe it, action to apply it, and persistence to continue$bp$, $bp$La révélation pour connaître la clé, la foi pour y croire, l'action pour l'appliquer et la persévérance pour continuer$bp$, TRUE, 0),
      ('a7403909-221c-483f-ad6d-49cbd180f4ec', 'cbc5e8d2-3547-4283-8fb1-2efd2b0ea0ca', $bp$Prayer to ask for the key, fasting to prepare for it, giving to pay for it, and rest to wait on it$bp$, $bp$La prière pour demander la clé, le jeûne pour s'y préparer, le don pour la payer et le repos pour l'attendre$bp$, FALSE, 1),
      ('774a27e7-ac88-4666-99b8-24ea48271478', 'cbc5e8d2-3547-4283-8fb1-2efd2b0ea0ca', $bp$Anointing to power the key, calling to direct it, favour to open it, and timing to release it$bp$, $bp$L'onction pour donner puissance à la clé, l'appel pour la diriger, la faveur pour l'ouvrir et le moment pour la libérer$bp$, FALSE, 2),
      ('6f1ded15-1b74-4e93-bedc-bdadbcf208b0', 'cbc5e8d2-3547-4283-8fb1-2efd2b0ea0ca', $bp$Teaching to learn the key, hearing to receive it, praise to celebrate it, and silence to guard it$bp$, $bp$L'enseignement pour apprendre la clé, l'écoute pour la recevoir, la louange pour la célébrer et le silence pour la garder$bp$, FALSE, 3),
      ('e8a954d2-65cd-41b7-baea-c3ebbc040f1d', '2a0c16ab-0e7e-4be8-a849-077bd09445fd', $bp$The oldest key that came before all others, promised first to the priests of Israel$bp$, $bp$La plus ancienne clé, venue avant toutes les autres, promise d'abord aux prêtres d'Israël$bp$, FALSE, 0),
      ('10d22f9e-40cc-4f95-b83f-009624ed6aee', '2a0c16ab-0e7e-4be8-a849-077bd09445fd', $bp$The private key that works apart from all others, kept for those called to teach$bp$, $bp$La clé privée qui fonctionne à part de toutes les autres, réservée à ceux appelés à enseigner$bp$, FALSE, 1),
      ('ef0fc06b-84cb-4ecf-a021-af52e27f18be', '2a0c16ab-0e7e-4be8-a849-077bd09445fd', $bp$The master key that governs all others, promised freely to all who ask$bp$, $bp$La clé maîtresse qui gouverne toutes les autres, promise librement à tous ceux qui demandent$bp$, TRUE, 2),
      ('4ec8776b-9a98-4aa2-8d2d-b90c6a54b962', '2a0c16ab-0e7e-4be8-a849-077bd09445fd', $bp$The final key that completes all others, promised only to those who have waited$bp$, $bp$La clé finale qui complète toutes les autres, promise seulement à ceux qui ont attendu$bp$, FALSE, 3),
      ('b2750b18-b592-4715-8317-d90814401aa4', '77ed36cf-f40a-4407-bfdb-0fabd13901b0', $bp$How do I use authority? These keys teach binding, loosing, and declaring on earth$bp$, $bp$Comment utiliser l'autorité ? Ces clés enseignent à lier, à délier et à déclarer sur la terre$bp$, FALSE, 0),
      ('45b3ed57-1677-4465-8746-f756ea42fadb', '77ed36cf-f40a-4407-bfdb-0fabd13901b0', $bp$How do I connect with Heaven? These keys open the channels of prayer and worship$bp$, $bp$Comment me connecter au Ciel ? Ces clés ouvrent les canaux de la prière et de l'adoration$bp$, FALSE, 1),
      ('36d86271-6274-446a-a902-ac966de8b67f', '77ed36cf-f40a-4407-bfdb-0fabd13901b0', $bp$How do I grow in character? These keys shape obedience, humility, and integrity$bp$, $bp$Comment grandir en caractère ? Ces clés façonnent l'obéissance, l'humilité et l'intégrité$bp$, FALSE, 2),
      ('d9120f6b-b1e4-4cc9-85ce-567b76d55bd9', '77ed36cf-f40a-4407-bfdb-0fabd13901b0', $bp$Who am I? These keys establish your identity and foundation as a Kingdom citizen$bp$, $bp$Qui suis-je ? Ces clés établissent votre identité et votre fondement comme citoyen du Royaume$bp$, TRUE, 3),
      ('0e274890-d417-4571-af33-403d8fd74e66', '4a1b35ec-bbab-404b-b2e5-98b3ca63cb0b', $bp$It means to borrow; the place in the Kingdom of Christ is on loan until Christ returns$bp$, $bp$Il signifie emprunter ; la place dans le Royaume de Christ est prêtée jusqu'au retour de Christ$bp$, FALSE, 0),
      ('f74411c7-fcfe-46b9-9a84-dd8d9b7ff83d', '4a1b35ec-bbab-404b-b2e5-98b3ca63cb0b', $bp$It means to transport; the move from darkness to the Kingdom of Christ is instant$bp$, $bp$Il signifie transporter ; le passage des ténèbres au Royaume de Christ est instantané$bp$, TRUE, 1),
      ('e8fbd6bc-4dff-4f43-a382-6b6809f68de5', '4a1b35ec-bbab-404b-b2e5-98b3ca63cb0b', $bp$It means to visit; the stay in the Kingdom of Christ is short and depends on behaviour$bp$, $bp$Il signifie visiter ; le séjour dans le Royaume de Christ est court et dépend du comportement$bp$, FALSE, 2),
      ('727f4755-860b-4da8-b138-61b293e4bd05', '4a1b35ec-bbab-404b-b2e5-98b3ca63cb0b', $bp$It means to improve; the change from darkness into the Kingdom of Christ is slow and gradual$bp$, $bp$Il signifie améliorer ; le passage des ténèbres au Royaume de Christ est lent et progressif$bp$, FALSE, 3),
      ('3d7bbcdf-91bb-4fa5-ab5d-753ffb01a4f5', '95e645a6-e7dc-4336-a79e-b0411ee5852f', $bp$He publicly honoured Jesus by bringing about a hundred pounds of spices for His burial$bp$, $bp$Il a honoré Jésus publiquement en apportant environ cent livres d'aromates pour Son ensevelissement$bp$, TRUE, 0),
      ('75c779df-a0ce-41a0-9dbb-36ab26ab75e7', '95e645a6-e7dc-4336-a79e-b0411ee5852f', $bp$He argued in the Sanhedrin that Jesus must be tried again before the whole nation$bp$, $bp$Il a soutenu au Sanhédrin que Jésus devait être jugé de nouveau devant toute la nation$bp$, FALSE, 1),
      ('d6d9688c-0375-4dba-81cf-717879528294', '95e645a6-e7dc-4336-a79e-b0411ee5852f', $bp$He secretly left Jerusalem by night, hiding from the council that had judged Jesus$bp$, $bp$Il a quitté Jérusalem en secret, de nuit, se cachant du conseil qui avait condamné Jésus$bp$, FALSE, 2),
      ('255d821a-c608-44ba-ac26-156fdbd99904', '95e645a6-e7dc-4336-a79e-b0411ee5852f', $bp$He gave away his wealth to the poor, and then followed Jesus around Galilee for years$bp$, $bp$Il a donné sa richesse aux pauvres, puis a suivi Jésus pendant des années en Galilée$bp$, FALSE, 3),
      ('20e85efd-242f-464a-895d-35b036daf7da', '5b5031e6-c64b-4959-82be-43aef117750b', $bp$It needs a strong battery to function, as the natural man needs strength to follow God$bp$, $bp$Il a besoin d'une forte pile pour fonctionner, comme l'homme naturel a besoin de force pour suivre Dieu$bp$, FALSE, 0),
      ('faf4bb4c-84fb-4956-b0a8-cba695d0c507', '5b5031e6-c64b-4959-82be-43aef117750b', $bp$It cannot pick up a frequency it was not built for, as the natural man cannot discern God$bp$, $bp$Il ne peut pas capter une fréquence pour laquelle il n'a pas été construit, comme l'homme naturel ne peut pas discerner Dieu$bp$, TRUE, 1),
      ('71002f54-a180-4e98-a31d-984010f83a5e', '5b5031e6-c64b-4959-82be-43aef117750b', $bp$It picks up many stations at once, as the natural man gets confused by many voices$bp$, $bp$Il capte beaucoup de stations à la fois, comme l'homme naturel est confus à cause de nombreuses voix$bp$, FALSE, 2),
      ('26de2639-cd8a-49f1-b908-582dc965f092', '5b5031e6-c64b-4959-82be-43aef117750b', $bp$It works better in some places than others, as the natural man hears God more in church$bp$, $bp$Il fonctionne mieux à certains endroits qu'à d'autres, comme l'homme naturel entend Dieu davantage à l'église$bp$, FALSE, 3),
      ('6b859845-5f86-4793-9599-da026d52324b', 'f2279c5e-0eb6-4364-9090-5af327faf161', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
